// 深拷贝时检测循环引用
Map<Object, Object> visited = new IdentityHashMap<>();
Object copy(Object src) {
    if (visited.containsKey(src)) return visited.get(src);
    Object dst = shallowClone(src); visited.put(src, dst);
    /* 递归复制字段 */ return dst;
}
